            BigDecimal taxaMensal = new BigDecimal("0.0199");
            BigDecimal fator = BigDecimal.ONE.add(taxaMensal).pow(parcelas * -1);
            BigDecimal divisor = BigDecimal.ONE.subtract(fator);
            BigDecimal taxaTotal = taxaMensal.divide(divisor, 10, RoundingMode.HALF_EVEN);
            BigDecimal valorJuros = total.multiply(taxaTotal);
            BigDecimal totalComJuros = total.add(valorJuros);
            totalComJuros = Arredondador.arredondar(totalComJuros);
            return totalComJuros.subtract(total);
        }
        return BigDecimal.ZERO;
    }

    private BigDecimal calcularValorParcela(BigDecimal totalFinal, FormaPagamento formaPagamento, Integer parcelas) {
        if (parcelas == null || parcelas <= 0) {
