        req.setParcelas(6);
        req.setNivelClube("BRONZE");

        RespostaCheckout resposta = calculadora.calcular(req);

        assertEquals(new BigDecimal("409.70"), resposta.getSubtotalProdutos());
        assertEquals(new BigDecimal("0.00"), resposta.getDescontoCupom());
